d=json.load(open(p))
print('keys', list(d.keys()))
# recursively collect input names and paths from d['inputs']
def walk(x,path=''):
    if isinstance(x,dict):
        name=x.get('name')
        label=x.get('label')
        typ=x.get('model_class')
        if name is not None:
            print(path+'|'+name, typ, label)
        for k,v in x.items():
            if k in ['inputs','cases']:
                if isinstance(v,list):
                    for i,it in enumerate(v):
                        walk(it, path + (f'[{k}.{i}]' if path else k+f'[{i}]'))
                elif isinstance(v,dict):
                    walk(v,path)
            elif isinstance(v,dict) and k not in ['options']:
                walk(v,path)
    elif isinstance(x,list):
        for i,it in enumerate(x):
            walk(it,path)
# top inputs
for inp in d.get('inputs',[]):
    walk(inp,'')
